// Undo one overreach from the identity merges, and bound another.
//
//     node scripts/fix-dc07-pc1203-postings.cjs
//     node scripts/fix-dc07-pc1203-postings.cjs --apply
//
// DC-07. Moving TM-16's 93 L onto DC-07 was evidenced by the daily sheets.
// Rewriting where DC-07 is POSTED was not, and it did harm: DC-07 is a double
// cab that changed site twelve times this year, and the open-ended Galagedara
// posting opened for it sent its Wadakada fills of 12 and 31 August to
// Galagedara as well. Its previous postings were generated by the system's own
// rule from its own fuel history, which is a better authority than a guess made
// while moving somebody else's fuel. So: delete the posting that was added and
// reopen the CEP-03W one that was closed.
//
// The consequence, stated plainly: DC-07's 93 L of Galagedara fuel bills to
// CEP-03W, because that is where the vehicle was posted on those days. Under
// this system's rule — fuel follows the vehicle, not the tank — that is the
// correct answer, and the Galagedara TANK report is unaffected either way.
//
// PC-1203. Created with an open-ended Galagedara posting from a single day's
// fill. Idle machines still bill in this system, so an open posting on a vehicle
// nothing else is known about accrues rental at Galagedara for ever. It is
// bounded to the one day the 10/08 sheet evidences. Extend it when the site says
// where the vehicle actually is.

const Database = require("better-sqlite3");
const { randomUUID } = require("crypto");
const fs = require("node:fs");

const APPLY = process.argv.includes("--apply");
const DB_PATH = process.env.DB || "D:/Fuel system server side/fuelsystem/data/app.db";
if (!fs.existsSync(DB_PATH)) {
  console.error(`\nno database at ${DB_PATH}\n  cwd is ${process.cwd()}\n`);
  process.exit(2);
}

const db = new Database(DB_PATH);
const now = new Date().toISOString().replace("Z", "+00:00");
const admin = db.prepare("SELECT id FROM User WHERE role='ADMIN' ORDER BY createdAt LIMIT 1").get();
const audit = (id, s) => db.prepare(
  `INSERT INTO AuditLog (id,actorId,action,entity,entityId,summary,createdAt) VALUES (?,?,?,?,?,?,?)`)
  .run(randomUUID(), admin.id, "UPDATE", "AssetAssignment", id, s, now);

const WHY =
  "Reverted 2026-09-03. Moving the 93 L onto DC-07 was evidenced by the daily sheets; rewriting its site posting " +
  "was not. DC-07 changed site twelve times this year, and an open-ended Galagedara posting billed its Wadakada " +
  "fills of 12 and 31 August to Galagedara too. Its 93 L of Galagedara fuel therefore bills to CEP-03W, where the " +
  "vehicle was posted at the time — fuel follows the vehicle, not the tank.";

const added = db.prepare(`
  SELECT g.id FROM AssetAssignment g JOIN Asset a ON a.id=g.assetId JOIN Project p ON p.id=g.projectId
  WHERE a.code='DC-07' AND p.code='CEP-03F' AND g.note LIKE 'Opened when TM-16%'`).get();

const closed = db.prepare(`
  SELECT g.id, g.startDate, g.endDate FROM AssetAssignment g JOIN Asset a ON a.id=g.assetId JOIN Project p ON p.id=g.projectId
  WHERE a.code='DC-07' AND p.code='CEP-03W' ORDER BY g.startDate DESC LIMIT 1`).get();

const pc = db.prepare(`
  SELECT g.id, g.startDate, g.endDate FROM AssetAssignment g JOIN Asset a ON a.id=g.assetId
  WHERE a.code='PC-1203'`).get();

console.log(`\n=== posting corrections (${APPLY ? "APPLY" : "DRY-RUN"}) ===\n`);
console.log(`  DC-07   delete the CEP-03F posting added today   ${added ? added.id.slice(0, 8) : "NOT FOUND"}`);
console.log(`  DC-07   reopen the CEP-03W posting closed today  ${closed ? `${closed.id.slice(0, 8)}  ${String(closed.startDate).slice(0, 10)} -> ${closed.endDate ? String(closed.endDate).slice(0, 10) : "open"}` : "NOT FOUND"}`);
console.log(`  PC-1203 bound its posting to one day            ${pc ? `${pc.id.slice(0, 8)}  ${String(pc.startDate).slice(0, 10)} -> ${pc.endDate ? String(pc.endDate).slice(0, 10) : "open"}` : "NOT FOUND"}`);

if (!APPLY) { console.log("\nDRY-RUN — nothing written. Re-run with --apply\n"); db.close(); process.exit(0); }

db.transaction(() => {
  if (added) {
    db.prepare("DELETE FROM AssetAssignment WHERE id=?").run(added.id);
    audit(added.id, `Deleted the CEP-03F posting opened for DC-07 earlier today. ${WHY}`);
  }
  if (closed && closed.endDate) {
    db.prepare("UPDATE AssetAssignment SET endDate=NULL, updatedAt=? WHERE id=?").run(now, closed.id);
    audit(closed.id, `Reopened DC-07's CEP-03W posting, which had been closed at ${String(closed.endDate).slice(0, 10)}. ${WHY}`);
  }
  if (pc && !pc.endDate) {
    db.prepare("UPDATE AssetAssignment SET endDate=?, updatedAt=? WHERE id=?").run(pc.startDate, now, pc.id);
    audit(pc.id, `Bounded PC-1203's CEP-03F posting to the single day the 10/08 daily sheet evidences. It was ` +
      `open-ended, and an open posting on a vehicle nothing else is known about accrues rental at Galagedara ` +
      `indefinitely — idle machines still bill in this system. Extend it when the site says where the vehicle is.`);
  }
})();

db.pragma("wal_checkpoint(TRUNCATE)");

console.log("\n  after — DC-07 and PC-1203 postings:");
for (const code of ["DC-07", "PC-1203"]) {
  for (const g of db.prepare(`
    SELECT p.code, g.startDate s, g.endDate e FROM AssetAssignment g
    JOIN Asset a ON a.id=g.assetId JOIN Project p ON p.id=g.projectId
    WHERE a.code=? ORDER BY g.startDate DESC LIMIT 3`).all(code)) {
    console.log(`    ${code.padEnd(9)}${g.code.padEnd(9)}${String(g.s).slice(0, 10)} -> ${g.e ? String(g.e).slice(0, 10) : "open"}`);
  }
}
console.log("");
db.close();
